// Records exchanged with the Rust side. The JSON the bundled Afterhours.exe
// prints (`status --json`, `check --json`) is generated from schemas/ into
// ./generated by `pnpm types`; the rest mirrors src-tauri/src.

export type { State as SessionState, Status, StatusReport } from "./generated/status";
export type { Preflight } from "./generated/check";
export type { VersionReport } from "./generated/version";
export type { SettingsReport } from "./generated/settings";
export type { StoryReport, StoryCheckpoint } from "./generated/story";
export type { Preview as StoryPreview } from "./generated/story-preview";
export type { Applied as StoryApplied } from "./generated/story-apply";
export type { MapImagesReport } from "./generated/map-images";
import type { Event as SessionEvent } from "./generated/event";
export type { SessionEvent };
export type { MapCar, MapDriver, MapWorld, TrafficRing } from "./generated/event";
/** A `map-feed` event of `--events`: where the cars are (capability `map-feed`). */
export type MapFeed = Extract<SessionEvent, { event: "map-feed" }>;
export type {
  Car,
  CarImage,
  CarImages,
  CarLocation,
  CarSummary,
  Cell,
  Columns,
  Counts,
  Profile,
  Reputation,
  Save,
} from "./generated/profile";
export type { ProfileEntry, ProfileList } from "./generated/profile-list";
export type {
  CrashDump,
  ServerLog,
  SessionFile,
  SessionList,
  SessionSummary,
  UnsupportedRoute,
} from "./generated/sessions";

/** One session file as the log viewer reads it (src-tauri/src/reads.rs). */
export interface SessionFileText {
  name: string;
  bytes: number;
  text: string;
  truncated: boolean;
}

export type CliResult =
  { kind: "ok"; value: unknown } | { kind: "error"; exit: number; message: string };

export type UpdateMode = "ask" | "auto" | "off";

export interface UpdateSettings {
  mode: UpdateMode;
  skipped_version: string | null;
}

export interface Settings {
  game_dir: string | null;
  data_dir: string | null;
  player_name: string | null;
  avatar: string | null;
  first_run_done: boolean;
  updates: UpdateSettings;
  last_server_tag: string | null;
  /** Your server on another PC on your network; `null` is this PC's own. */
  server: RemoteServer | null;
  /** The port and token the launcher gives its own server's API. */
  local_api: { port: number; token: string } | null;
  /** This PC's network address while your other PCs may use its server. */
  share_address: string | null;
  /** How many times the window has opened (src/lib/state/support.ts). */
  launches: number;
  /** When the Garage last showed the support line, UTC. */
  support_shown_utc: string | null;
}

/** A server on another PC: what its `api --json` prints there. */
export interface RemoteServer {
  /** `http://<IPv4 address>:<port>`. */
  url: string;
  /** Its API token, 64 lowercase hexadecimal characters. */
  token: string;
}

export type OutputLine =
  | { kind: "status"; time: string; state: string; message: string }
  | { kind: "text"; text: string }
  /** The launcher's own line about the server in use (src-tauri/src/connlog.rs). */
  | { kind: "launcher"; time: string; message: string; detail: string };

/** What closing the launcher does while this PC's shared server runs. */
export type CloseAction = "ask" | "keep" | "stop";

/** A server on another PC, as paired (src-tauri/src/servers.rs). */
export interface ServerEntry {
  id: string;
  name: string;
  /** `http://<IPv4 address>:<port>`. */
  url: string;
  token: string;
  added_utc: string;
  last_seen_utc: string | null;
  last_version: string | null;
  last_capabilities: string[];
  last_played_utc: string | null;
}

/** `servers.json`: your servers and which one is in use. */
export interface Servers {
  version: number;
  servers: ServerEntry[];
  /** The entry in use; `null` is this PC's own server. */
  in_use: string | null;
  close_action: CloseAction;
  this_pc: { last_played_utc: string | null };
}

/** What a check of a server found. */
export type Reach =
  | {
      state: "online";
      version: string;
      release: string;
      capabilities: string[];
      ping_ms: number;
      session: string | null;
      game_running: boolean;
      saves: number | null;
    }
  | { state: "unreachable"; message: string }
  | { state: "refused"; message: string }
  | { state: "older"; message: string };

/** `server_check`: a pairing code looked at before saving. */
export type ServerCheck = Reach & {
  url: string;
  address: string;
  /** That is this PC's own server. */
  own: boolean;
  /** Already saved, under this name. */
  known_as: string | null;
};

/** One saved server as the Server screen last saw it. */
export type ServerHealth = Reach & { id: string; checked_utc: string };

export function emptyServers(): Servers {
  return {
    version: 1,
    servers: [],
    in_use: null,
    close_action: "ask",
    this_pc: { last_played_utc: null },
  };
}

export type SessionAction = "setup" | "serve" | "start";

/** `status --json` as the server answered it. */
export type StatusProbe = { kind: "ok"; state: string } | { kind: "error"; message: string };

/** The current session as the data directory's records describe it. */
export type Recorded =
  | { kind: "none" }
  | {
      kind: "session";
      id: string;
      state: string;
      message: string;
      utc: string;
      /** Probed only for a live state; null when it could not be. */
      lock_held: boolean | null;
    }
  | { kind: "error"; message: string };

export interface Activity {
  cli: StatusProbe;
  recorded: Recorded;
  window_session: boolean;
}

export interface BackedUpFile {
  path: string;
  bytes: number;
  sha256: string;
}

export interface BackupReport {
  folder: string | null;
  files: BackedUpFile[];
}

export interface ServerInfo {
  repository: string;
  pinned_tag: string;
  pinned_sha256: string;
  override_allowed: boolean;
  path: string | null;
  source: "bundled" | "override" | null;
  version_line: string | null;
  matches_pin: boolean | null;
  /** From `version --json`; null for servers without it (v0.3.0). */
  capabilities: string[] | null;
  error: string | null;
}

export interface AppInfo {
  launcher_version: string;
  server: ServerInfo;
  data_dir: string | null;
  /** The launcher's own folder when it holds the game: then the game folder in use. */
  game_in_launcher_folder: string | null;
  updater: {
    endpoint: string | null;
    configured: boolean;
    /** Running from the no-install ZIP: updates open their download page. */
    portable: boolean;
  };
  debug_build: boolean;
  /** The signed-in user's name, for "Hide my user name"; `null` when unknown. */
  user_name: string | null;
}

export type Folder = "data" | "session" | "backups";

export function emptySettings(): Settings {
  return {
    game_dir: null,
    data_dir: null,
    player_name: null,
    avatar: null,
    first_run_done: false,
    updates: { mode: "ask", skipped_version: null },
    last_server_tag: null,
    server: null,
    local_api: null,
    share_address: null,
    launches: 0,
    support_shown_utc: null,
  };
}
